// RED (partial): blocksFor/parityFor do not exist yet until C3 GREEN.
import { decodeQR } from '../../src/codec/qr-decoder.js';

/**
 * Format-information robustness and cross-level decoding.
 *
 * 1. Golden vectors generated by an independent ISO-conformant encoder
 *    (python-qrcode lineage) at every EC level - proves our reader accepts
 *    vendor codes regardless of level/mask choice.
 * 2. Both-copy bit corruption within Hamming distance 3 recovers cleanly.
 * 3. Fully destroyed format still fails closed.
 */

function synthesize(matrix, scale = 4) {
    const quiet = 4;
    const dim = (matrix.size + quiet * 2) * scale;
    const data = new Uint8ClampedArray(dim * dim * 4).fill(255);
    for (let r = 0; r < matrix.size; r++) {
        for (let c = 0; c < matrix.size; c++) {
            if (!matrix.modules[r * matrix.size + c]) continue;
            for (let py = 0; py < scale; py++) {
                for (let px = 0; px < scale; px++) {
                    const y = (r + quiet) * scale + py;
                    const x = (c + quiet) * scale + px;
                    const i = (y * dim + x) * 4;
                    data[i] = 0; data[i + 1] = 0; data[i + 2] = 0;
                }
            }
        }
    }
    return { data, width: dim, height: dim };
}

/** Renders a borderless row-string grid into RGBA. */
function synthRows(rows, scale = 4) {
    const size = rows.length;
    const quiet = 4;
    const dim = (size + quiet * 2) * scale;
    const data = new Uint8ClampedArray(dim * dim * 4).fill(255);
    for (let r = 0; r < size; r++) {
        for (let c = 0; c < size; c++) {
            if (rows[r][c] === '0') continue;
            for (let py = 0; py < scale; py++) {
                for (let px = 0; px < scale; px++) {
                    const y = (r + quiet) * scale + py;
                    const x = (c + quiet) * scale + px;
                    const i = (y * dim + x) * 4;
                    data[i] = 0; data[i + 1] = 0; data[i + 2] = 0;
                }
            }
        }
    }
    return { data, width: dim, height: dim };
}

