describe('QR capacity: all four EC levels', () => {
    it('block tables exist for every level x version', () => {
        for (let ecl = 0; ecl <= 3; ecl++) {
            for (let v = 1; v <= 15; v++) {
                const blocks = blocksFor(ecl, v);
                if (!blocks || !blocks.length) throw new Error(`ecl${ecl} v${v}: missing blocks`);
            }
        }
    });

    it('derived totals are identical across levels (ISO invariant)', () => {
        for (let v = 1; v <= 15; v++) {
            for (let ecl = 0; ecl <= 3; ecl++) {
                const blocks = blocksFor(ecl, v);
                const nB = blocks.reduce((a, b) => a + b.count, 0);
                const dCw = blocks.reduce((a, b) => a + b.count * b.data, 0);
                if (dCw + nB * parityFor(ecl, v) !== totalCodewords(v)) {
                    throw new Error(`ecl${ecl} v${v}: derived total mismatch`);
                }
            }
        }
    });

    it('spot-checks golden non-M structures', () => {
        // ISO tables: L v10 = 2x(68+18)+2x(69+18); H v6 = 4x(15+28);
        // Q v13 = 8x(20+24)+4x(21+24)
        expect(JSON.stringify(blocksFor(EC_LEVEL_BITS.L, 10)))
            .toEqual(JSON.stringify([{ count: 2, data: 68 }, { count: 2, data: 69 }]));
        expect(parityFor(EC_LEVEL_BITS.L, 10)).toEqual(18);
        expect(JSON.stringify(blocksFor(EC_LEVEL_BITS.H, 6)))
            .toEqual(JSON.stringify([{ count: 4, data: 15 }]));
        expect(parityFor(EC_LEVEL_BITS.H, 6)).toEqual(28);
        expect(JSON.stringify(blocksFor(EC_LEVEL_BITS.Q, 13)))
            .toEqual(JSON.stringify([{ count: 8, data: 20 }, { count: 4, data: 21 }]));
        expect(parityFor(EC_LEVEL_BITS.Q, 13)).toEqual(24);
    });
});

describe('QR decode: independent golden vectors across EC levels', () => {
    for (const vec of GOLDEN_VECTORS) {
        it(`decodes ${vec.text.slice(15, 16)} (${vec.rows.length}x${vec.rows.length})`, () => {
            const [result, err] = decodeQR(synthRows(vec.rows));
            expect(err).toEqual(null);
            if (!result) throw new Error('no result');
            expect(new TextDecoder().decode(result.bytes)).toBe(vec.text);
        });
    }
});

describe('QR decode: format information tolerance', () => {
    /** Physical cell lists for both format copies (mirrors encoder writer). */
    function formatCells(size) {
        const a = [];
        for (let i = 0; i <= 5; i++) a.push([i, 8]);
        a.push([7, 8], [8, 8], [8, 7]);
        for (let i = 5; i >= 0; i--) a.push([8, i]);
        const b = [];
        for (let i = size - 1; i >= size - 7; i--) b.push([i, 8]);
        for (let i = size - 8; i < size; i++) b.push([8, i]);
        return [a, b];
    }

    function corruptBothCopies(matrix, bitIdxs) {
        const [cellsA, cellsB] = formatCells(matrix.size);
        for (const bi of bitIdxs) {
            matrix.modules[cellsA[bi][0] * matrix.size + cellsA[bi][1]] ^= 1;
            matrix.modules[cellsB[bi][0] * matrix.size + cellsB[bi][1]] ^= 1;
        }
        return matrix;
    }

    it('recovers when one bit is corrupted in BOTH copies (Hamming 1)', () => {
        const uri = 'otpauth://totp/x?secret=JBSWY3DPEHPK3PXP';
        const m = encodeQR(new TextEncoder().encode(uri));
        corruptBothCopies(m, [3]);
        const [result, err] = decodeQR(synthesize(m));
        expect(err).toEqual(null);
        expect(new TextDecoder().decode(result.bytes)).toBe(uri);
    });

    it('recovers when two bits are corrupted in BOTH copies (Hamming 2)', () => {
        const uri = 'otpauth://totp/x?secret=JBSWY3DPEHPK3PXP';
        const m = encodeQR(new TextEncoder().encode(uri));
        corruptBothCopies(m, [3, 11]);
        const [result, err] = decodeQR(synthesize(m));
        expect(err).toEqual(null);
        expect(new TextDecoder().decode(result.bytes)).toBe(uri);
    });

    it('still fails closed when format is fully destroyed', () => {
        const m = encodeQR(new TextEncoder().encode('otpauth://totp/dead?secret=JBSWY3DPEHPK3PXP'));
        const [cellsA, cellsB] = formatCells(m.size);
        // All-dark strips sit at Hamming distance 5 from EVERY canonical
        // format string - beyond the tolerance floor - and, unlike varied
        // patterns, stay constant under the sampler's origin sweep.
        for (const cells of [cellsA, cellsB]) {
            for (const [r, c] of cells) m.modules[r * m.size + c] = 1;
        }
        const [, err] = decodeQR(synthesize(m));
        if (!(err instanceof Error)) throw new Error('destroyed format accepted');
        // Destroyed strips may trip the Hamming fallback into a wrong-mask
        // read that RS then rejects - either way decoding must FAIL.
        void err.message;
    });
});
